package com.campuskart; import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.*; @WebServlet("/image") public class ImageServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT image_data,image_type FROM products WHERE id=?")){p.setInt(1,Integer.parseInt(r.getParameter("id")));try(ResultSet x=p.executeQuery()){if(x.next()){s.setContentType(x.getString("image_type"));try(InputStream in=x.getBinaryStream("image_data");OutputStream out=s.getOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}}}catch(Exception e){s.sendError(404);}}}